import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

/**
 * Convert Three.js scene to OBJ format with Blender Z-up space rotation
 */
function exportSceneToOBJ(scene, outputPath) {
  // Create a rotation matrix for -90 degrees around X-axis (Blender Z-up conversion)
  const blenderRotation = new THREE.Matrix4();
  const xRotation = new THREE.Euler(-Math.PI / 2, 0, 0, 'XYZ');
  blenderRotation.makeRotationFromEuler(xRotation);

  // Collect all vertices, normals, and faces
  const vertices = [];
  const normals = [];
  const faces = [];
  let vertexOffset = 0;

  // Traverse the scene and collect all meshes
  scene.traverse((object) => {
    if (object instanceof THREE.Mesh) {
      // Get the geometry
      const geometry = object.geometry;

      // Create a combined matrix (world position + rotation + scale + Blender rotation)
      const worldMatrix = new THREE.Matrix4();
      object.updateWorldMatrix(true, false);
      worldMatrix.copy(object.matrixWorld);

      // Apply Blender rotation
      const finalMatrix = new THREE.Matrix4();
      finalMatrix.multiplyMatrices(blenderRotation, worldMatrix);

      // Get position attribute
      const positionAttribute = geometry.getAttribute('position');
      if (!positionAttribute) continue;

      // Get normal attribute (create if not present)
      let normalAttribute = geometry.getAttribute('normal');
      if (!normalAttribute) {
        geometry.computeVertexNormals();
        normalAttribute = geometry.getAttribute('normal');
      }

      // Extract vertices and apply transformations
      const tempVector = new THREE.Vector3();
      const tempNormal = new THREE.Vector3();
      const normalMatrix = new THREE.Matrix3().getNormalMatrix(finalMatrix);

      for (let i = 0; i < positionAttribute.count; i++) {
        tempVector.fromBufferAttribute(positionAttribute, i);
        tempVector.applyMatrix4(finalMatrix);
        vertices.push(tempVector.x, tempVector.y, tempVector.z);

        // Transform normals
        tempNormal.fromBufferAttribute(normalAttribute, i);
        tempNormal.applyMatrix3(normalMatrix).normalize();
        normals.push(tempNormal.x, tempNormal.y, tempNormal.z);
      }

      // Extract faces
      const indexAttribute = geometry.getIndex();
      if (indexAttribute) {
        for (let i = 0; i < indexAttribute.count; i += 3) {
          const a = indexAttribute.getX(i) + vertexOffset + 1;
          const b = indexAttribute.getX(i + 1) + vertexOffset + 1;
          const c = indexAttribute.getX(i + 2) + vertexOffset + 1;
          faces.push([a, b, c]);
        }
      } else {
        // Non-indexed geometry
        for (let i = 0; i < positionAttribute.count; i += 3) {
          const a = i + vertexOffset + 1;
          const b = i + 1 + vertexOffset + 1;
          const c = i + 2 + vertexOffset + 1;
          faces.push([a, b, c]);
        }
      }

      vertexOffset += positionAttribute.count;
    }
  });

  // Build OBJ file content
  let objContent = '# Three.js Scene Export\n';
  objContent += `# Vertices: ${vertices.length / 3}\n`;
  objContent += `# Faces: ${faces.length}\n`;
  objContent += '# Blender Z-up conversion applied (-90° X-rotation)\n\n';

  // Write vertices
  for (let i = 0; i < vertices.length; i += 3) {
    objContent += `v ${vertices[i].toFixed(6)} ${vertices[i + 1].toFixed(6)} ${vertices[i + 2].toFixed(6)}\n`;
  }

  objContent += '\n';

  // Write normals
  for (let i = 0; i < normals.length; i += 3) {
    objContent += `vn ${normals[i].toFixed(6)} ${normals[i + 1].toFixed(6)} ${normals[i + 2].toFixed(6)}\n`;
  }

  objContent += '\n';

  // Write faces
  for (const face of faces) {
    const [a, b, c] = face;
    objContent += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
  }

  // Ensure output directory exists
  const outputDir = path.dirname(outputPath);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write to file
  fs.writeFileSync(outputPath, objContent, 'utf-8');
  console.log(`✓ OBJ file exported successfully to: ${outputPath}`);
  console.log(`  - Vertices: ${vertices.length / 3}`);
  console.log(`  - Faces: ${faces.length}`);
  console.log(`  - Blender Z-up rotation applied (−90° X-axis)`);
}

// Main execution
try {
  const scene = createScene();
  const outputPath = '/root/output/object.obj';

  console.log('Starting Three.js to OBJ conversion...');
  exportSceneToOBJ(scene, outputPath);
  console.log('Conversion complete!');
} catch (error) {
  console.error('Error during export:', error.message);
  process.exit(1);
}

